try {
  const d = JSON.parse(msg.payload);
  const parts = msg.topic.split('/');
  const id = parts[1] || context.global.get('online_device_id') || 'device';
  return [
    { payload: d.rate },
    { payload: d, deviceId: id },
    { payload: d.pres, topic: id + ' pres' }
  ];
} catch(e) { return [null,null,null]; }

try {
  const d = JSON.parse(msg.payload);
  if (d.id) context.global.set('online_device_id', d.id);
  msg.payload = { state: d.state, id: d.id, fw: d.fw || 'sim', online: d.state === 'online' };
  return msg;
} catch(e) { return null; }

try {
  const d = (typeof msg.payload === 'object') ? msg.payload : JSON.parse(msg.payload);
  const now = new Date();
  const pad = (n, s=2) => String(n).padStart(s, '0');
  const t = pad(now.getHours()) + ':' + pad(now.getMinutes()) + ':' + pad(now.getSeconds());
  const CORE1 = [
    'ESPERANDO (UNHOMED)','HOMING','REL_LSW_INI','LISTO EN HOME',
    'BUSCANDO JERINGA','JERINGA ACOPLADA','DISPENSANDO','FIN DE DISPENSADO',
    'NUEVO DISPENSADO','BUSCANDO EOT','REL_LSW_FIN','FIN DE RECORRIDO',
    'FALLA MOTOR','OCLUSIÓN FRENANDO','LIBERANDO OCLUSIÓN','PAUSA POR OCLUSIÓN',
    'MANUAL OVERRIDE','CALIB INI (BUSCA 0)','CALIB FIN (BUSCA MAX)','FRENANDO LSW INI','FRENANDO LSW FIN'
  ];
  let log = context.global.get('event_log') || [];
  let detail, fsmMsg = null;
  if (d.type === 'alarm') {
    detail = 'ALARMA ' + (d.code||'').toUpperCase() + ' lvl ' + d.level;
  } else if (d.type === 'state') {
    const from = CORE1[d.from] !== undefined ? CORE1[d.from] : String(d.from);
    const to   = CORE1[d.to]   !== undefined ? CORE1[d.to]   : String(d.to);
    detail = from + ' → ' + to;
    context.global.set('fsm_state', d.to);
    fsmMsg = { payload: { fsm_from: d.from, fsm_to: d.to } };
  } else {
    detail = d.msg || JSON.stringify(d);
  }
  log.unshift({ time: t, tipo: d.type || 'info', detalle: detail });
  if (log.length > 30) log = log.slice(0, 30);
  context.global.set('event_log', log);
  const notif = d.type === 'alarm'
    ? { payload: '⚠ ALARMA: ' + (d.code||'').toUpperCase() + ' (nivel ' + d.level + ')', topic: 'error' }
    : null;
  return [{ payload: log }, notif, fsmMsg];
} catch(e) {
  node.error('fn_event: ' + e.message, msg);
  return [null, null, null];
}

try {
  const d = (typeof msg.payload === 'object') ? msg.payload : JSON.parse(msg.payload);
  const now = new Date();
  const pad = (n, s=2) => String(n).padStart(s, '0');
  const t = `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;
  const res = d.result || 'unknown';
  const detail = '#' + d.cid + ': ' + res + (d.reason ? ' (' + d.reason + ')' : '');
  let log = context.global.get('event_log') || [];
  log.unshift({ time: t, tipo: 'ack', detalle: detail });
  if (log.length > 30) log = log.slice(0, 30);
  context.global.set('event_log', log);
  return [
    { payload: detail, result: res, cid: d.cid },
    { payload: log }
  ];
} catch(e) {
  return [null, null];
}

const devId = context.global.get('online_device_id') || 'bj-deadbeef';
let cid = (context.global.get('cmd_cid') || 0) + 1;
context.global.set('cmd_cid', cid);
msg.topic = 'bj/' + devId + '/cmd';
msg.payload = JSON.stringify({ cid: cid, cmd: String(msg.payload) });
return msg;

const devId = context.global.get('online_device_id') || 'bj-deadbeef';
msg.topic = 'bj/' + devId + '/sim_fault';
return msg;

let p = msg.payload;
if (typeof p === 'object') {
  try { p = JSON.stringify(p); } catch(e) {}
} else {
  p = String(p);
}
const now = new Date();
const pad = (n, s=2) => String(n).padStart(s, '0');
const tStr = `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}.${pad(now.getMilliseconds(), 3)}`;
let log = context.get('term_log') || [];
const newItem = {
  id: msg._msgid || (Date.now() + '-' + Math.random()),
  ts: now.getTime(),
  topic: msg.topic || '',
  data: p,
  qos: msg.qos !== undefined ? msg.qos : 0,
  retain: !!msg.retain,
  time: tStr
};
log.push(newItem);
if (log.length > 200) {
  log.shift();
}
context.set('term_log', log);
return { payload: log };

try {
  const d = (typeof msg.payload === 'object') ? msg.payload : JSON.parse(msg.payload);
  const now = new Date();
  const pad = (n, s=2) => String(n).padStart(s, '0');
  d._ts = `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}.${pad(now.getMilliseconds(), 3)}`;
  const parts = (msg.topic || '').split('/');
  d._devId = parts[1] || 'device';
  return { payload: d };
} catch(e) {
  return null;
}

try {
  const d = (typeof msg.payload === 'object') ? msg.payload : JSON.parse(msg.payload);
  const adc = d.adc || {};
  const now = Date.now();
  const last = context.get('last_sample') || 0;
  if (now - last < 2000) {
    return null;
  }
  context.set('last_sample', now);
  const frcV = (typeof adc.frc_sens_v === 'number') ? adc.frc_sens_v : 0;
  const bubV = (typeof adc.bub_sens_v === 'number') ? adc.bub_sens_v : 0;
  const vinV = (typeof adc.vin_sens_v === 'number') ? adc.vin_sens_v : 0;
  return [
    { topic: 'FRC_SENS (V)', payload: frcV },
    { topic: 'BUB_SENS (V)', payload: bubV },
    { topic: 'VIN_SENS (V)', payload: vinV }
  ];
} catch(e) {
  return null;
}

const defaultCfg = {
  frc: { mode: 'dynamic', min: 0.0, max: 3.3 },
  bub: { mode: 'dynamic', min: 0.0, max: 3.3 },
  vin: { mode: 'dynamic', min: 10.0, max: 26.0 }
};

let current = context.global.get('trends_scale_config') || defaultCfg;

function cleanNum(val, defVal) {
  if (val === undefined || val === null || val === '') return defVal;
  const n = parseFloat(String(val).replace(',', '.'));
  return isNaN(n) ? defVal : n;
}

const input = msg.payload;

if (typeof input === 'string') {
  if (input === 'dynamic') {
    current.frc.mode = 'dynamic';
    current.bub.mode = 'dynamic';
    current.vin.mode = 'dynamic';
  } else if (input === 'fixed') {
    current.frc.mode = 'fixed';
    current.frc.min = 0.0;
    current.frc.max = 3.3;
    current.bub.mode = 'fixed';
    current.bub.min = 0.0;
    current.bub.max = 3.3;
    current.vin.mode = 'fixed';
    current.vin.min = 10.0;
    current.vin.max = 26.0;
  }
} else if (typeof input === 'object' && input !== null) {
  ['frc', 'bub', 'vin'].forEach(ch => {
    if (input[ch]) {
      if (input[ch].mode) current[ch].mode = input[ch].mode;
      if (input[ch].min !== undefined) current[ch].min = cleanNum(input[ch].min, current[ch].min);
      if (input[ch].max !== undefined) current[ch].max = cleanNum(input[ch].max, current[ch].max);
      if (current[ch].min >= current[ch].max) {
        current[ch].max = current[ch].min + 1.0;
      }
    }
  });
}

context.global.set('trends_scale_config', current);

function getChartOptions(ch, defMin, defMax) {
  const conf = current[ch];
  if (conf.mode === 'fixed') {
    return {
      ui_update: {
        chartOptions: {
          yAxis: {
            min: defMin,
            max: defMax
          }
        }
      }
    };
  } else if (conf.mode === 'custom') {
    return {
      ui_update: {
        chartOptions: {
          yAxis: {
            min: conf.min,
            max: conf.max
          }
        }
      }
    };
  } else {
    return {
      ui_update: {
        chartOptions: {
          yAxis: {
            min: null,
            max: null
          }
        }
      }
    };
  }
}

const frcMsg = getChartOptions('frc', 0.0, 3.3);
const bubMsg = getChartOptions('bub', 0.0, 3.3);
const vinMsg = getChartOptions('vin', 10.0, 26.0);

const navMsg = {
  payload: JSON.parse(JSON.stringify(current))
};

return [frcMsg, bubMsg, vinMsg, navMsg];

try {
  const d = (typeof msg.payload === 'object') ? msg.payload : JSON.parse(msg.payload);
  const topicParts = (msg.topic || '').split('/');
  const devId = topicParts[1] || 'default';

  // Guardar estado individual por dispositivo
  const allStates = context.global.get('syringe_states') || {};
  const state = allStates[devId] || {
    devId: devId,
    progress_pct: 0.0,
    position_mm: 0.0,
    speed_ums: 0.0,
    infused_ml: 0.0,
    target_ml: 0.0,
    rate_ml_h: 0.0,
    fsm_state: 3,
    lastUpdate: 0
  };

  if (d.progress_pct !== undefined) state.progress_pct = Number(d.progress_pct);
  if (d.position_mm !== undefined) state.position_mm = Number(d.position_mm);
  if (d.speed_ums !== undefined) state.speed_ums = Number(d.speed_ums);
  if (d.infused_ml !== undefined) state.infused_ml = Number(d.infused_ml);
  if (d.target_ml !== undefined) {
    state.target_ml = Number(d.target_ml);
    if (state.target_ml > 0 && d.progress_pct === undefined) {
      state.progress_pct = Math.min(100, (state.infused_ml / state.target_ml) * 100);
    }
  }
  if (d.rate_ml_h !== undefined) state.rate_ml_h = Number(d.rate_ml_h);
  if (d.fsm_state !== undefined) state.fsm_state = Number(d.fsm_state);
  state.lastUpdate = Date.now();

  allStates[devId] = state;
  context.global.set('syringe_states', allStates);

  // Si este dispositivo está en 0% idle, pero otro dispositivo está infundiendo activamente, no sobrescribir la UI
  if (state.progress_pct === 0 && state.fsm_state !== 6) {
    for (const [otherId, otherState] of Object.entries(allStates)) {
      if (otherId !== devId && (otherState.fsm_state === 6 || otherState.progress_pct > 0) && (Date.now() - otherState.lastUpdate < 3000)) {
        return [null, null, null];
      }
    }
  }

  context.global.set('syringe_state', state);

  const msgSyringe = { payload: state };
  const msgRate = (state.rate_ml_h !== undefined) ? { payload: state.rate_ml_h } : null;
  const msgStats = {
    payload: {
      vol_inf: state.infused_ml,
      vol_tgt: state.target_ml,
      t_ela_s: state.elapsed_s || 0,
      t_rem_h: (state.rate_ml_h > 0 && state.target_ml > state.infused_ml) 
        ? ((state.target_ml - state.infused_ml) / state.rate_ml_h) : 0
    }
  };

  return [msgSyringe, msgRate, msgStats];
} catch(e) {
  return [null, null, null];
}
